/**
 * Event Bus - Simple publish/subscribe system for inter-service communication
 */

type EventHandler = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventHandler[]> = new Map();

  /**
   * Subscribe to an event by name
   */
  subscribe(eventName: string, handler: EventHandler): void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, []);
    }
    this.subscribers.get(eventName)!.push(handler);
  }

  /**
   * Publish an event with a payload
   */
  publish(eventName: string, payload: any): void {
    const handlers = this.subscribers.get(eventName);
    if (handlers) {
      handlers.forEach((handler) => {
        try {
          handler(payload);
        } catch (error) {
          console.error(`Error handling event ${eventName}:`, error);
        }
      });
    }
  }
}

export const eventBus = new EventBus();

/**
 * User Service - Manages user data
 */

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  /**
   * Create a new user
   */
  createUser(name: string, email: string): User {
    const user: User = {
      id: randomUUID(),
      name,
      email,
    };
    this.users.set(user.id, user);
    return user;
  }

  /**
   * Get a user by ID
   */
  getUser(id: string): User | null {
    return this.users.get(id) || null;
  }

  /**
   * Get all users
   */
  getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  /**
   * Update a user
   */
  updateUser(id: string, updates: Partial<User>): User | null {
    const user = this.users.get(id);
    if (!user) return null;

    const updated: User = {
      ...user,
      ...updates,
      id: user.id, // Ensure ID doesn't change
    };
    this.users.set(id, updated);
    return updated;
  }

  /**
   * Delete a user
   */
  deleteUser(id: string): boolean {
    return this.users.delete(id);
  }
}

/**
 * Project Service - Manages projects
 */

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  members: string[]; // User IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  /**
   * Create a new project
   */
  createProject(name: string, description: string): Project {
    const project: Project = {
      id: randomUUID(),
      name,
      description,
      members: [],
    };
    this.projects.set(project.id, project);
    return project;
  }

  /**
   * Get a project by ID
   */
  getProject(id: string): Project | null {
    return this.projects.get(id) || null;
  }

  /**
   * Get all projects
   */
  getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  /**
   * Update a project
   */
  updateProject(id: string, updates: Partial<Project>): Project | null {
    const project = this.projects.get(id);
    if (!project) return null;

    const updated: Project = {
      ...project,
      ...updates,
      id: project.id, // Ensure ID doesn't change
    };
    this.projects.set(id, updated);
    return updated;
  }

  /**
   * Delete a project
   */
  deleteProject(id: string): boolean {
    return this.projects.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    if (!project.members.includes(userId)) {
      project.members.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    project.members = project.members.filter((id) => id !== userId);
    return project;
  }
}

/**
 * Task Service - Manages tasks with status transitions
 */

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  assignee: string | null; // User ID
  createdAt: number;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private statusOrder: TaskStatus[] = ['todo', 'in-progress', 'done'];

  constructor(private eventBus: EventBus) {}

  /**
   * Create a new task
   */
  createTask(
    projectId: string,
    title: string,
    description: string
  ): Task {
    const task: Task = {
      id: randomUUID(),
      projectId,
      title,
      description,
      status: 'todo',
      assignee: null,
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);
    return task;
  }

  /**
   * Get a task by ID
   */
  getTask(id: string): Task | null {
    return this.tasks.get(id) || null;
  }

  /**
   * Get all tasks
   */
  getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  /**
   * Get tasks for a specific project
   */
  getTasksByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  /**
   * Update a task
   */
  updateTask(id: string, updates: Partial<Task>): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const updated: Task = {
      ...task,
      ...updates,
      id: task.id, // Ensure ID doesn't change
      projectId: task.projectId, // Ensure project ID doesn't change
      createdAt: task.createdAt, // Ensure creation time doesn't change
    };
    this.tasks.set(id, updated);
    return updated;
  }

  /**
   * Delete a task
   */
  deleteTask(id: string): boolean {
    return this.tasks.delete(id);
  }

  /**
   * Validate and update task status
   * Status transitions: todo -> in-progress -> done
   */
  updateTaskStatus(id: string, newStatus: TaskStatus): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const currentIndex = this.statusOrder.indexOf(task.status);
    const newIndex = this.statusOrder.indexOf(newStatus);

    if (newIndex < currentIndex) {
      throw new Error(
        `Cannot transition from '${task.status}' to '${newStatus}'. Can only move forward in status.`
      );
    }

    const updated = this.updateTask(id, { status: newStatus });

    if (updated) {
      this.eventBus.publish('task.status-changed', {
        taskId: id,
        oldStatus: task.status,
        newStatus: newStatus,
        assignee: updated.assignee,
      });
    }

    return updated;
  }

  /**
   * Assign a task to a user
   */
  assignTask(id: string, userId: string): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const updated = this.updateTask(id, { assignee: userId });

    if (updated) {
      this.eventBus.publish('task.assigned', {
        taskId: id,
        userId: userId,
        taskTitle: updated.title,
      });
    }

    return updated;
  }

  /**
   * Unassign a task
   */
  unassignTask(id: string): Task | null {
    return this.updateTask(id, { assignee: null });
  }
}

/**
 * Comment Service - Manages comments on tasks
 */

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  createdAt: number;
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus) {}

  /**
   * Create a new comment
   */
  createComment(taskId: string, authorId: string, text: string): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId,
      authorId,
      text,
      createdAt: Date.now(),
    };
    this.comments.set(comment.id, comment);

    // Publish event for notification service
    this.eventBus.publish('comment.added', {
      commentId: comment.id,
      taskId,
      authorId,
      text,
    });

    return comment;
  }

  /**
   * Get a comment by ID
   */
  getComment(id: string): Comment | null {
    return this.comments.get(id) || null;
  }

  /**
   * Get all comments
   */
  getAllComments(): Comment[] {
    return Array.from(this.comments.values());
  }

  /**
   * Get comments for a specific task
   */
  getCommentsByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  /**
   * Delete a comment
   */
  deleteComment(id: string): boolean {
    return this.comments.delete(id);
  }
}

/**
 * Notification Service - Manages notifications for users
 */

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';
import { TaskService } from './task-service';
import { UserService } from './user-service';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(
    private eventBus: EventBus,
    private taskService: TaskService,
    private userService: UserService
  ) {
    this.setupEventListeners();
  }

  /**
   * Set up listeners for relevant events
   */
  private setupEventListeners(): void {
    // Listen for task assignments
    this.eventBus.subscribe('task.assigned', (payload: any) => {
      const user = this.userService.getUser(payload.userId);
      if (user) {
        this.createNotification(
          payload.userId,
          `You have been assigned to task: "${payload.taskTitle}"`
        );
      }
    });

    // Listen for task status changes
    this.eventBus.subscribe('task.status-changed', (payload: any) => {
      const task = this.taskService.getTask(payload.taskId);
      if (task && payload.assignee) {
        this.createNotification(
          payload.assignee,
          `Task status changed from "${payload.oldStatus}" to "${payload.newStatus}"`
        );
      }
    });

    // Listen for comments added
    this.eventBus.subscribe('comment.added', (payload: any) => {
      const task = this.taskService.getTask(payload.taskId);
      if (task && task.assignee && task.assignee !== payload.authorId) {
        const author = this.userService.getUser(payload.authorId);
        const authorName = author?.name || 'Someone';
        this.createNotification(
          task.assignee,
          `${authorName} commented on your task: "${payload.text.substring(0, 50)}..."`
        );
      }
    });
  }

  /**
   * Create a new notification
   */
  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      timestamp: Date.now(),
    };
    this.notifications.set(notification.id, notification);
    return notification;
  }

  /**
   * Get a notification by ID
   */
  getNotification(id: string): Notification | null {
    return this.notifications.get(id) || null;
  }

  /**
   * Get all notifications
   */
  getAllNotifications(): Notification[] {
    return Array.from(this.notifications.values());
  }

  /**
   * Get notifications for a specific user
   */
  getNotificationsByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(
      (notification) => notification.userId === userId
    );
  }

  /**
   * Mark a notification as read
   */
  markAsRead(id: string): Notification | null {
    const notification = this.notifications.get(id);
    if (!notification) return null;

    notification.read = true;
    return notification;
  }

  /**
   * Delete a notification
   */
  deleteNotification(id: string): boolean {
    return this.notifications.delete(id);
  }
}

/**
 * API Router - Handles HTTP requests and routes them to appropriate services
 */

import { IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export class APIRouter {
  constructor(
    private userService: UserService,
    private projectService: ProjectService,
    private taskService: TaskService,
    private commentService: CommentService,
    private notificationService: NotificationService
  ) {}

  /**
   * Main request handler
   */
  async handleRequest(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const urlObj = parseUrl(req.url || '', true);
    const pathname = urlObj.pathname || '';
    const method = req.method || 'GET';

    try {
      // Users routes
      if (pathname === '/users' && method === 'GET') {
        return this.respondJSON(res, 200, this.userService.getAllUsers());
      }
      if (pathname === '/users' && method === 'POST') {
        return this.handleCreateUser(req, res);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'GET') {
        return this.handleGetUser(pathname, res);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'PUT') {
        return this.handleUpdateUser(pathname, req, res);
      }
      if (pathname.match(/^\/users\/[^/]+$/) && method === 'DELETE') {
        return this.handleDeleteUser(pathname, res);
      }

      // Projects routes
      if (pathname === '/projects' && method === 'GET') {
        return this.respondJSON(res, 200, this.projectService.getAllProjects());
      }
      if (pathname === '/projects' && method === 'POST') {
        return this.handleCreateProject(req, res);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'GET') {
        return this.handleGetProject(pathname, res);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'PUT') {
        return this.handleUpdateProject(pathname, req, res);
      }
      if (pathname.match(/^\/projects\/[^/]+$/) && method === 'DELETE') {
        return this.handleDeleteProject(pathname, res);
      }
      if (pathname.match(/^\/projects\/[^/]+\/members$/) && method === 'POST') {
        return this.handleAddMember(pathname, req, res);
      }
      if (pathname.match(/^\/projects\/[^/]+\/members$/) && method === 'DELETE') {
        return this.handleRemoveMember(pathname, req, res);
      }

      // Tasks routes
      if (pathname === '/tasks' && method === 'GET') {
        return this.handleGetTasks(urlObj.query, res);
      }
      if (pathname === '/tasks' && method === 'POST') {
        return this.handleCreateTask(req, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'GET') {
        return this.handleGetTask(pathname, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'PUT') {
        return this.handleUpdateTask(pathname, req, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+$/) && method === 'DELETE') {
        return this.handleDeleteTask(pathname, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+\/status$/) && method === 'PUT') {
        return this.handleUpdateTaskStatus(pathname, req, res);
      }
      if (pathname.match(/^\/tasks\/[^/]+\/assign$/) && method === 'PUT') {
        return this.handleAssignTask(pathname, req, res);
      }

      // Comments routes
      if (pathname === '/comments' && method === 'GET') {
        return this.handleGetComments(urlObj.query, res);
      }
      if (pathname === '/comments' && method === 'POST') {
        return this.handleCreateComment(req, res);
      }
      if (pathname.match(/^\/comments\/[^/]+$/) && method === 'GET') {
        return this.handleGetComment(pathname, res);
      }
      if (pathname.match(/^\/comments\/[^/]+$/) && method === 'DELETE') {
        return this.handleDeleteComment(pathname, res);
      }

      // Notifications routes
      if (pathname === '/notifications' && method === 'GET') {
        return this.handleGetNotifications(urlObj.query, res);
      }
      if (pathname.match(/^\/notifications\/[^/]+\/read$/) && method === 'PUT') {
        return this.handleMarkNotificationAsRead(pathname, res);
      }

      // Not found
      return this.respondJSON(res, 404, { error: 'Not found' });
    } catch (error) {
      console.error('Request error:', error);
      return this.respondJSON(res, 500, { error: 'Internal server error' });
    }
  }

  // User handlers
  private async handleCreateUser(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const body = await this.parseBody(req);
    const { name, email } = body;
    if (!name || !email) {
      return this.respondJSON(res, 400, {
        error: 'Missing required fields: name, email',
      });
    }
    const user = this.userService.createUser(name, email);
    return this.respondJSON(res, 201, user);
  }

  private handleGetUser(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const user = this.userService.getUser(id);
    if (!user) {
      return this.respondJSON(res, 404, { error: 'User not found' });
    }
    return this.respondJSON(res, 200, user);
  }

  private async handleUpdateUser(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = this.extractId(pathname);
    const body = await this.parseBody(req);
    const user = this.userService.updateUser(id, body);
    if (!user) {
      return this.respondJSON(res, 404, { error: 'User not found' });
    }
    return this.respondJSON(res, 200, user);
  }

  private handleDeleteUser(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const success = this.userService.deleteUser(id);
    if (!success) {
      return this.respondJSON(res, 404, { error: 'User not found' });
    }
    return this.respondJSON(res, 204, null);
  }

  // Project handlers
  private async handleCreateProject(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const body = await this.parseBody(req);
    const { name, description } = body;
    if (!name || !description) {
      return this.respondJSON(res, 400, {
        error: 'Missing required fields: name, description',
      });
    }
    const project = this.projectService.createProject(name, description);
    return this.respondJSON(res, 201, project);
  }

  private handleGetProject(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const project = this.projectService.getProject(id);
    if (!project) {
      return this.respondJSON(res, 404, { error: 'Project not found' });
    }
    return this.respondJSON(res, 200, project);
  }

  private async handleUpdateProject(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = this.extractId(pathname);
    const body = await this.parseBody(req);
    const project = this.projectService.updateProject(id, body);
    if (!project) {
      return this.respondJSON(res, 404, { error: 'Project not found' });
    }
    return this.respondJSON(res, 200, project);
  }

  private handleDeleteProject(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const success = this.projectService.deleteProject(id);
    if (!success) {
      return this.respondJSON(res, 404, { error: 'Project not found' });
    }
    return this.respondJSON(res, 204, null);
  }

  private async handleAddMember(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const projectId = this.extractId(pathname.replace('/members', ''));
    const body = await this.parseBody(req);
    const { userId } = body;
    if (!userId) {
      return this.respondJSON(res, 400, { error: 'Missing userId' });
    }
    const project = this.projectService.addMember(projectId, userId);
    if (!project) {
      return this.respondJSON(res, 404, { error: 'Project not found' });
    }
    return this.respondJSON(res, 200, project);
  }

  private async handleRemoveMember(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const projectId = this.extractId(pathname.replace('/members', ''));
    const body = await this.parseBody(req);
    const { userId } = body;
    if (!userId) {
      return this.respondJSON(res, 400, { error: 'Missing userId' });
    }
    const project = this.projectService.removeMember(projectId, userId);
    if (!project) {
      return this.respondJSON(res, 404, { error: 'Project not found' });
    }
    return this.respondJSON(res, 200, project);
  }

  // Task handlers
  private handleGetTasks(query: any, res: ServerResponse): void {
    let tasks = this.taskService.getAllTasks();
    if (query.projectId) {
      tasks = this.taskService.getTasksByProject(query.projectId);
    }
    return this.respondJSON(res, 200, tasks);
  }

  private async handleCreateTask(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const body = await this.parseBody(req);
    const { projectId, title, description } = body;
    if (!projectId || !title || !description) {
      return this.respondJSON(res, 400, {
        error: 'Missing required fields: projectId, title, description',
      });
    }
    const task = this.taskService.createTask(projectId, title, description);
    return this.respondJSON(res, 201, task);
  }

  private handleGetTask(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const task = this.taskService.getTask(id);
    if (!task) {
      return this.respondJSON(res, 404, { error: 'Task not found' });
    }
    return this.respondJSON(res, 200, task);
  }

  private async handleUpdateTask(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = this.extractId(pathname);
    const body = await this.parseBody(req);
    const task = this.taskService.updateTask(id, body);
    if (!task) {
      return this.respondJSON(res, 404, { error: 'Task not found' });
    }
    return this.respondJSON(res, 200, task);
  }

  private handleDeleteTask(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const success = this.taskService.deleteTask(id);
    if (!success) {
      return this.respondJSON(res, 404, { error: 'Task not found' });
    }
    return this.respondJSON(res, 204, null);
  }

  private async handleUpdateTaskStatus(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = this.extractId(pathname.replace('/status', ''));
    const body = await this.parseBody(req);
    const { status } = body;
    if (!status) {
      return this.respondJSON(res, 400, { error: 'Missing status' });
    }
    try {
      const task = this.taskService.updateTaskStatus(id, status);
      if (!task) {
        return this.respondJSON(res, 404, { error: 'Task not found' });
      }
      return this.respondJSON(res, 200, task);
    } catch (error: any) {
      return this.respondJSON(res, 400, { error: error.message });
    }
  }

  private async handleAssignTask(
    pathname: string,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = this.extractId(pathname.replace('/assign', ''));
    const body = await this.parseBody(req);
    const { userId } = body;
    if (!userId) {
      return this.respondJSON(res, 400, { error: 'Missing userId' });
    }
    const task = this.taskService.assignTask(id, userId);
    if (!task) {
      return this.respondJSON(res, 404, { error: 'Task not found' });
    }
    return this.respondJSON(res, 200, task);
  }

  // Comment handlers
  private handleGetComments(query: any, res: ServerResponse): void {
    let comments = this.commentService.getAllComments();
    if (query.taskId) {
      comments = this.commentService.getCommentsByTask(query.taskId);
    }
    return this.respondJSON(res, 200, comments);
  }

  private async handleCreateComment(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const body = await this.parseBody(req);
    const { taskId, authorId, text } = body;
    if (!taskId || !authorId || !text) {
      return this.respondJSON(res, 400, {
        error: 'Missing required fields: taskId, authorId, text',
      });
    }
    const comment = this.commentService.createComment(taskId, authorId, text);
    return this.respondJSON(res, 201, comment);
  }

  private handleGetComment(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const comment = this.commentService.getComment(id);
    if (!comment) {
      return this.respondJSON(res, 404, { error: 'Comment not found' });
    }
    return this.respondJSON(res, 200, comment);
  }

  private handleDeleteComment(pathname: string, res: ServerResponse): void {
    const id = this.extractId(pathname);
    const success = this.commentService.deleteComment(id);
    if (!success) {
      return this.respondJSON(res, 404, { error: 'Comment not found' });
    }
    return this.respondJSON(res, 204, null);
  }

  // Notification handlers
  private handleGetNotifications(query: any, res: ServerResponse): void {
    let notifications = this.notificationService.getAllNotifications();
    if (query.userId) {
      notifications = this.notificationService.getNotificationsByUser(query.userId);
    }
    return this.respondJSON(res, 200, notifications);
  }

  private handleMarkNotificationAsRead(
    pathname: string,
    res: ServerResponse
  ): void {
    const id = this.extractId(pathname.replace('/read', ''));
    const notification = this.notificationService.markAsRead(id);
    if (!notification) {
      return this.respondJSON(res, 404, { error: 'Notification not found' });
    }
    return this.respondJSON(res, 200, notification);
  }

  // Helper methods
  private extractId(pathname: string): string {
    const parts = pathname.split('/').filter((p) => p);
    return parts[parts.length - 1];
  }

  private async parseBody(req: IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let body = '';
      req.on('data', (chunk) => {
        body += chunk.toString();
      });
      req.on('end', () => {
        try {
          resolve(body ? JSON.parse(body) : {});
        } catch (error) {
          reject(error);
        }
      });
      req.on('error', reject);
    });
  }

  private respondJSON(
    res: ServerResponse,
    statusCode: number,
    data: any
  ): void {
    res.writeHead(statusCode, { 'Content-Type': 'application/json' });
    if (statusCode === 204) {
      res.end();
    } else {
      res.end(JSON.stringify(data));
    }
  }
}

